dsc='Free checker: does your Scottish holiday let qualify for non-domestic (business) rates? 140 nights available, 70 nights let, evidence by 26 May, or council tax and the second-home premium. Official sources.'
b=f'''<p class="lead">Enter your nights for one financial year (1 April to 31 March) to see whether your self-catering property in Scotland should be on the non-domestic rates roll, or will be charged council tax instead.</p>
<form id="sbr" class="box" onsubmit="return false">
<p><label><b>Nights available to let</b> in the financial year (advertised and bookable on a commercial basis)<br><input type="number" id="avail" min="0" max="366" inputmode="numeric" required></label></p>
<p><label><b>Nights actually let</b> in that year (paying guests only; free stays by family or friends do not count)<br><input type="number" id="let" min="0" max="366" inputmode="numeric" required></label></p>
<p><label><input type="checkbox" id="main"> The property is someone's only or main home</label><br>
<label><input type="checkbox" id="comm" checked> It is let commercially as short-term self-catering, with a view to profit</label></p>
<button type="button" id="go">Check</button></form>
<div id="result" class="box" hidden aria-live="polite"><h2 id="rh"></h2><div id="rt"></div><h3>Get told when Scottish rules change</h3><p>One short, sourced email a week.</p>{FORM}<p class="small"><b>Not legal or tax advice.</b> The local Assessor decides. Always check the official sources below.</p></div>
<h2>The rules in brief</h2><ul>
<li>To be rated as self-catering holiday accommodation, the property must <b>not be anyone's only or main residence</b>, be <b>available to let commercially for 140+ nights</b> and <b>actually let for 70+ nights</b> in the financial year (1 April to 31 March).</li>
<li>You must <b>prove it to the Assessor every year</b>: booking calendars and adverts (availability), and booking dates and income per booking (lettings). Explain any booking over 28 nights. If you self-advertise, include bank statements.</li>
<li><b>Deadline:</b> evidence must reach the Assessor <b>before 27 May</b> (i.e. by 26 May) after the year ends. If the Assessor asks after the year ends, you have 56 days from the request. Late or insufficient evidence means the property goes on the <b>council tax list</b> for that year.</li>
<li>Council tax on a second home: since 1 April 2024 councils can charge a <b>premium of up to 100%</b> (double). A second home is furnished, not anyone's main home and lived in for at least 25 days a year. 29 of 32 councils announced the full premium for 2024 (not Falkirk, Glasgow or North Ayrshire; North Ayrshire has charged it since 1 April 2025); check your council for its current policy.</li>
<li>You also need a short-term let licence, whichever tax applies.</li></ul>
<h2>Official sources</h2><ul>{"".join(f'<li><a href="{u}" rel="nofollow">{t}</a></li>' for t,u in RS)}</ul>
<script>
function sbrCheck(a,l,main,comm){{if(isNaN(a)||isNaN(l)||a<0||l<0||a>366||l>366)return 'invalid';if(l>a)return 'letgtavail';if(main)return 'main';if(!comm)return 'noncomm';if(a>=140&&l>=70)return 'rates';if(a<140&&l<70)return 'ct_both';return a<140?'ct_avail':'ct_let';}}
(function(){{var R=document.getElementById('result'),H=document.getElementById('rh'),T=document.getElementById('rt');
var EV='<p><b>Next steps:</b></p><ol><li>Gather booking calendars and adverts showing the nights available, plus a booking summary (from Airbnb, Sykes, Booking.com etc.) with dates and income for each booking. Explain any booking over 28 nights. Self-advertised? Add redacted bank statements.</li><li>Complete the self-catering declaration on the <a href="https://www.saa.gov.uk/non-domestic-valuation/self-catering/">Scottish Assessors website</a> and send your evidence <b>by 26 May</b> after the financial year ends (or within 56 days if the Assessor writes to you after the year has ended).</li><li>Check whether you qualify for <a href="https://www.mygov.scot/non-domestic-rates-guidance/short-term-lets">rates relief</a>.</li></ol>';
var CT='<p>The property is likely to be on the <b>council tax list</b> for that year. If it is furnished, nobody\\'s main home and lived in for at least 25 days a year, it counts as a <b>second home</b> and your council may charge a <b>premium of up to 100%</b> (double council tax). Most councils do. Check your council\\'s policy.</p><p><b>Next steps:</b> contact your council\\'s council tax team, and if you expect to meet the thresholds next year, keep calendars, adverts and booking records from 1 April so you can send evidence to the Assessor by 26 May.</p>';
var M={{invalid:['Check your numbers','<p>Enter whole numbers between 0 and 366.</p>'],
letgtavail:['Check your numbers','<p>Nights let cannot be more than nights available. The 70 let nights must fall within the nights it was available to let.</p>'],
main:['Council tax, not business rates','<p>A property that is someone\\'s only or main residence cannot be classed as self-catering holiday accommodation, so it stays on the council tax list.</p>'],
noncomm:['Probably council tax','<p>To be rated it must be let on a commercial basis with a view to profit. Non-commercial lettings to family or friends do not count.</p>'+CT],
rates:['Likely to qualify for non-domestic (business) rates','<p>You meet both thresholds: at least 140 nights available and at least 70 nights let. You must still <b>prove this to the Assessor</b> for every financial year, or the property moves to council tax.</p>'+EV],
ct_avail:['Does not qualify: fewer than 140 nights available',CT],ct_let:['Does not qualify: fewer than 70 nights let',CT],ct_both:['Does not qualify: below both thresholds',CT]}};
document.getElementById('go').addEventListener('click',function(){{var a=parseInt(document.getElementById('avail').value,10),l=parseInt(document.getElementById('let').value,10);
var k=sbrCheck(a,l,document.getElementById('main').checked,document.getElementById('comm').checked);H.textContent=M[k][0];T.innerHTML=M[k][1];R.hidden=false;R.dataset.result=k;}});}})();
</script>'''
t='Scotland self-catering business rates checker (140/70 nights)'
page('scotland-business-rates-checker.html','Does my Scottish holiday let pay business rates or council tax?',b,desc=dsc,full_title=t+' | UK Short-Let Rules Tracker',head=OGT('scotland-business-rates-checker.html',t,dsc))

